cat << 'EOF' > src/nsh.pest
WHITESPACE = _{ " " | "\t" }
COMMENT = _{ "#" ~ (!"\n" ~ ANY)* }

script = { SOI ~ compound_list ~ EOI }

compound_list = { compound_list_item* }
compound_list_item = { and_or_list ~ (compound_list_sep | EOI)? | compound_list_sep }
compound_list_sep = { ";" | normal_newline | "&" }
normal_newline = { "\n" }

and_or_list = { pipeline ~ (and_or_list_sep ~ pipeline)* }
and_or_list_sep = { "&&" | "||" }

pipeline = { command ~ ("|" ~ command)* ~ "&"? }

command = {
    if_stmt
  | while_stmt
  | for_stmt
  | case_stmt
  | func_def
  | local_stmt
  | break_stmt
  | continue_stmt
  | subshell
  | block
  | simple_command
}

if_stmt = { "if" ~ compound_list ~ "then" ~ compound_list ~ (elif_clause)* ~ ("else" ~ compound_list)? ~ "fi" }
elif_clause = { "elif" ~ compound_list ~ "then" ~ compound_list }

while_stmt = { "while" ~ compound_list ~ "do" ~ compound_list ~ "done" }

for_stmt = {
    "for" ~ "((" ~ arith_for_exprs ~ "))" ~ (";" | normal_newline)* ~ "do" ~ compound_list ~ "done"
  | "for" ~ var_name ~ ("in" ~ word*)? ~ (";" | normal_newline)* ~ "do" ~ compound_list ~ "done"
}
arith_for_exprs = { (!"))" ~ ANY)* }

case_stmt = { "case" ~ word ~ "in" ~ (case_item)* ~ "esac" }
case_item = { pattern_list ~ ")" ~ compound_list ~ ";;"? }
pattern_list = { word ~ ("|" ~ word)* }

func_def = { ("function" ~ var_name ~ "()" | var_name ~ "()") ~ compound_list_body }
block = { "{" ~ compound_list ~ "}" }
subshell = { "(" ~ compound_list ~ ")" }
compound_list_body = { "{" ~ compound_list ~ "}" }

local_stmt = { "local" ~ var_assignment }
break_stmt = { "break" }
continue_stmt = { "continue" }

simple_command = { (redirect | var_assignment | word)+ }

var_assignment = { var_name ~ "=" ~ word? }
var_name = @ { (ASCII_ALPHA | "_") ~ (ASCII_ALPHANUMERIC | "_")* }

redirect = {
    redirect_direction ~ word
  | "2>&1"
  | "1>&2"
  | ">&2"
  | heredoc
}
redirect_direction = { "2>>" | "2>" | ">>" | ">" | "<" }

heredoc = { "<<" ~ heredoc_delimiter }
heredoc_delimiter = @ { (ASCII_ALPHANUMERIC | "_" | "'" | "\"")* }

word = ${ (quoted_str | param_expansion | arith_expansion | cmd_subst | escaped_char | word_char)+ }
word_char = @ { !(" " | "\t" | "\n" | ";" | "|" | "&" | "(" | ")" | "<" | ">" | "{" | "}") ~ ANY }
escaped_char = @ { "\\" ~ ANY }

quoted_str = ${ double_quoted | single_quoted }
double_quoted = ${ "\"" ~ (param_expansion | cmd_subst | escaped_char | (!"\"" ~ ANY))* ~ "\"" }
single_quoted = ${ "'" ~ (!"'" ~ ANY)* ~ "'" }

param_expansion = ${ "${" ~ param_expr ~ "}" | "$" ~ (var_name | ASCII_DIGIT | "?" | "!" | "#" | "$" | "*" | "@") }
param_expr = ${ ("#" ~ var_name) | (var_name ~ (param_op ~ param_arg)?) }
param_op = { ":-" | ":=" | "-" | "=" | "//" | "/" }
param_arg = { (!"}" ~ ANY)* }

arith_expansion = ${ "$((" ~ (!"))" ~ ANY)* ~ "))" }
cmd_subst = ${ "$(" ~ (!")" ~ ANY)* ~ ")" | "`" ~ (!"`" ~ ANY)* ~ "`" }
EOF"}

