use crate::shell::Shell;

pub enum BuiltinResult {
    Success,
    Exit(i32),
    Error(i32),
}

pub fn is_builtin(cmd: &str) -> bool {
    matches!(
        cmd,
        "cd" | "echo"
            | "exit"
            | "export"
            | "unset"
            | "alias"
            | "jobs"
            | "fg"
            | "bg"
            | "source"
            | "exec"
            | "set"
            | "read"
            | "shift"
            | "wait"
            | "pushd"
            | "popd"
    )
}

pub fn run_builtin(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.is_empty() {
        return BuiltinResult::Success;
    }
    let cmd = args[0].as_str();
    let argv = &args[1..];

    match cmd {
        "cd" => builtin_cd(shell, argv),
        "echo" => builtin_echo(shell, argv),
        "exit" => builtin_exit(shell, argv),
        "export" => builtin_export(shell, argv),
        "unset" => builtin_unset(shell, argv),
        "alias" => builtin_alias(shell, argv),
        "jobs" => builtin_jobs(shell, argv),
        "fg" => builtin_fg(shell, argv),
        "bg" => builtin_bg(shell, argv),
        "source" => builtin_source(shell, argv),
        "exec" => builtin_exec(shell, argv),
        "set" => builtin_set(shell, argv),
        "read" => builtin_read(shell, argv),
        "shift" => builtin_shift(shell, argv),
        "wait" => builtin_wait(shell, argv),
        "pushd" => builtin_pushd(shell, argv),
        "popd" => builtin_popd(shell, argv),
        _ => BuiltinResult::Error(1),
    }
}

fn builtin_cd(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    let target = if args.is_empty() {
        shell.get_env("HOME").unwrap_or_else(|| "/".to_string())
    } else if args[0] == "-" {
        match shell.get_env("OLDPWD") {
            Some(old) => old,
            None => {
                eprintln!("nsh: cd: OLDPWD not set");
                return BuiltinResult::Error(1);
            }
        }
    } else if args[0] == "~" || args[0].starts_with("~/") {
        let home = shell.get_env("HOME").unwrap_or_else(|| "/".to_string());
        if args[0] == "~" {
            home
        } else {
            format!("{}/{}", home, &args[0][2..])
        }
    } else {
        args[0].clone()
    };

    let p = Path::new(&target);
    match env::set_current_dir(p) {
        Ok(_) => {
            if let Ok(cwd) = env::current_dir() {
                let cwd_str = cwd.to_string_lossy().to_string();
                if let Some(old_pwd) = shell.get_env("PWD") {
                    shell.set_env("OLDPWD", &old_pwd);
                }
                shell.set_env("PWD", &cwd_str);
            }
            BuiltinResult::Success
        }
        Err(e) => {
            eprintln!("nsh: cd: {}: `{}`", e, target);
            BuiltinResult::Error(1)
        }
    }
}

fn builtin_echo(_shell: &mut Shell, args: &[String]) -> BuiltinResult {
    let mut no_newline = false;
    let mut enable_escapes = false;
    let mut idx = 0;

    while idx < args.len() {
        let arg = &args[idx];
        if arg == "-n" {
            no_newline = true;
            idx += 1;
        } else if arg == "-e" {
            enable_escapes = true;
            idx += 1;
        } else if arg == "-ne" || arg == "-en" {
            no_newline = true;
            enable_escapes = true;
            idx += 1;
        } else {
            break;
        }
    }

    let words = &args[idx..];
    let output = words.join(" ");

    let formatted = if enable_escapes {
        expand_echo_escapes(&output)
    } else {
        output
    };

    if no_newline {
        print!("{}", formatted);
    } else {
        println!("{}", formatted);
    }
    use std::io::Write;
    let _ = std::io::stdout().flush();

    BuiltinResult::Success
}

fn expand_echo_escapes(s: &str) -> String {
    let mut res = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&next) = chars.peek() {
                match next {
                    'n' => { res.push('\n'); chars.next(); }
                    't' => { res.push('\t'); chars.next(); }
                    'r' => { res.push('\r'); chars.next(); }
                    '\\' => { res.push('\\'); chars.next(); }
                    'a' => { res.push('\x07'); chars.next(); }
                    'b' => { res.push('\x08'); chars.next(); }
                    'f' => { res.push('\x0c'); chars.next(); }
                    'v' => { res.push('\x0b'); chars.next(); }
                    'e' => { res.push('\x1b'); chars.next(); }
                    _ => { res.push('\\'); }
                }
            } else {
                res.push('\\');
            }
        } else {
            res.push(c);
        }
    }
    res
}

fn builtin_exit(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.is_empty() {
        return BuiltinResult::Exit(shell.last_status);
    }
    if args.len() > 1 {
        return BuiltinResult::Error(1);
    }
    match args[0].parse::<i32>() {
        Ok(code) => BuiltinResult::Exit((code % 256 + 256) % 256),
        Err(_) => BuiltinResult::Error(1),
    }
}

fn builtin_export(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.is_empty() {
        return BuiltinResult::Success;
    }
    for arg in args {
        if let Some((k, v)) = arg.split_once('=') {
            shell.set_env(k, v);
            env::set_var(k, v);
        } else {
            if let Some(v) = shell.get_var(arg) {
                env::set_var(arg, v);
            }
            shell.export_var(arg);
        }
    }
    BuiltinResult::Success
}

fn builtin_unset(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) {
        println!("nsh: unset: unset 0.4.2\nSet command.\n\nUSAGE:\n    unset <NAME>\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nARGS:\n    <NAME>    ");
        return BuiltinResult::Success;
    }
    if args.contains(&"-V".to_string()) || args.contains(&"--version".to_string()) {
        println!("unset 0.4.2");
        return BuiltinResult::Success;
    }
    if args.is_empty() {
        eprintln!("nsh: unset: error: The following required arguments were not provided:\n    <NAME>\n\nUSAGE:\n    unset <NAME>\n\nFor more information try --help");
        return BuiltinResult::Error(1);
    }
    for arg in args {
        shell.unset_var(arg);
        env::remove_var(arg);
    }
    BuiltinResult::Success
}

fn builtin_alias(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.is_empty() {
        let mut keys: Vec<&String> = shell.aliases.keys().collect();
        keys.sort();
        for k in keys {
            if let Some(v) = shell.aliases.get(k) {
                println!("{}='{}'", k, v);
            }
        }
        return BuiltinResult::Success;
    }
    for arg in args {
        if let Some((k, v)) = arg.split_once('=') {
            let clean_v = v.trim_matches('\'').trim_matches('"');
            shell.aliases.insert(k.to_string(), clean_v.to_string());
        } else {
            eprintln!("nsh: alias:  --> 1:1\n  |\n1 | {}\n  | ^---\n  |\n  = expected alias", arg);
            return BuiltinResult::Error(1);
        }
    }
    BuiltinResult::Success
}

fn builtin_jobs(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) {
        println!("fg: jobs 0.4.2\njobs command.\n\nUSAGE:\n    jobs\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information");
        return BuiltinResult::Success;
    }
    if args.contains(&"-V".to_string()) || args.contains(&"--version".to_string()) {
        println!("jobs 0.4.2");
        return BuiltinResult::Success;
    }
    shell.list_jobs();
    BuiltinResult::Success
}

fn builtin_fg(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) {
        println!("nsh: fg: fg 0.4.2\nfg command.\n\nUSAGE:\n    fg [job_id]\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nARGS:\n    <job_id>    ");
        return BuiltinResult::Success;
    }
    if args.contains(&"-V".to_string()) || args.contains(&"--version".to_string()) {
        println!("fg 0.4.2");
        return BuiltinResult::Success;
    }
    if shell.jobs.is_empty() {
        eprintln!("nsh: no jobs to run");
        return BuiltinResult::Error(1);
    }
    BuiltinResult::Success
}

fn builtin_bg(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) {
        println!("bg: bg 0.4.2\nbg command.\n\nUSAGE:\n    bg [job_id]\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nARGS:\n    <job_id>    ");
        return BuiltinResult::Success;
    }
    if args.contains(&"-V".to_string()) || args.contains(&"--version".to_string()) {
        println!("bg 0.4.2");
        return BuiltinResult::Success;
    }
    if shell.jobs.is_empty() {
        eprintln!("nsh: no jobs to run");
        return BuiltinResult::Error(1);
    }
    BuiltinResult::Success
}

fn builtin_source(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.is_empty() {
        eprintln!("nsh: source: filename argument required");
        return BuiltinResult::Error(1);
    }
    let filepath = &args[0];
    match std::fs::read_to_string(filepath) {
        Ok(content) => shell.eval_script(&content),
        Err(e) => {
            eprintln!("nsh: failed open the file: {:?}", e);
            BuiltinResult::Error(1)
        }
    }
}

fn builtin_exec(_shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.is_empty() {
        return BuiltinResult::Success;
    }
    let cmd = &args[0];
    let mut command = std::process::Command::new(cmd);
    if args.len() > 1 {
        command.args(&args[1..]);
    }
    use std::os::unix::process::CommandExt;
    let err = command.exec();
    eprintln!("nsh: exec: ENOENT: {}", err);
    BuiltinResult::Error(127)
}

fn builtin_set(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) {
        println!("nsh: set: set 0.4.2\nSet command.\n\nUSAGE:\n    set [FLAGS]\n\nFLAGS:\n    -e               \n    -h, --help       Prints help information\n    -n               \n    -u               \n    -V, --version    Prints version information");
        return BuiltinResult::Success;
    }
    if args.contains(&"-V".to_string()) || args.contains(&"--version".to_string()) {
        println!("set 0.4.2");
        return BuiltinResult::Success;
    }
    for arg in args {
        match arg.as_str() {
            "-e" => shell.flag_e = true,
            "+e" => shell.flag_e = false,
            "-u" => shell.flag_u = true,
            "+u" => shell.flag_u = false,
            "-n" => shell.flag_n = true,
            "+n" => shell.flag_n = false,
            _ => {}
        }
    }
    BuiltinResult::Success
}

fn builtin_read(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) {
        println!("read: read 0.4.2\nread command.\n\nUSAGE:\n    read [OPTIONS] <VAR>\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nOPTIONS:\n    -p <prompt>        \n\nARGS:\n    <VAR>    ");
        return BuiltinResult::Success;
    }
    if args.contains(&"-V".to_string()) || args.contains(&"--version".to_string()) {
        println!("read 0.4.2");
        return BuiltinResult::Success;
    }

    let mut prompt = None;
    let mut var = None;
    let mut idx = 0;
    while idx < args.len() {
        if args[idx] == "-p" {
            if idx + 1 < args.len() {
                prompt = Some(args[idx + 1].clone());
                idx += 2;
            } else {
                idx += 1;
            }
        } else {
            var = Some(args[idx].clone());
            idx += 1;
        }
    }

    let var_name = match var {
        Some(v) => v,
        None => {
            eprintln!("read: error: The following required arguments were not provided:\n    <VAR>\n\nUSAGE:\n    read [OPTIONS] <VAR>\n\nFor more information try --help");
            return BuiltinResult::Error(1);
        }
    };

    if let Some(p) = prompt {
        print!("{}", p);
        use std::io::Write;
        let _ = std::io::stdout().flush();
    }

    let mut input = String::new();
    if std::io::stdin().read_line(&mut input).is_ok() {
        let trimmed = input.trim_end_matches(&['\r', '\n'][..]);
        shell.set_var(&var_name, trimmed);
        BuiltinResult::Success
    } else {
        BuiltinResult::Error(1)
    }
}

fn builtin_shift(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) {
        println!("shift: shift 0.4.2\nshift command.\n\nUSAGE:\n    shift [n]\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nARGS:\n    <n>    ");
        return BuiltinResult::Success;
    }
    let n: usize = args.get(0).and_then(|s| s.parse().ok()).unwrap_or(1);
    shell.shift_positional_args(n);
    BuiltinResult::Success
}

fn builtin_wait(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) {
        println!("wait: wait 0.4.2\nwait command.\n\nUSAGE:\n    wait [job_id]\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nARGS:\n    <job_id>    ");
        return BuiltinResult::Success;
    }
    shell.wait_for_jobs();
    BuiltinResult::Success
}

fn builtin_pushd(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) {
        println!("nsh: pushd: pushd 0.4.2\nPushd command.\n\nUSAGE:\n    pushd [dir]\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nARGS:\n    <dir>    ");
        return BuiltinResult::Success;
    }
    if let Some(d) = args.get(0) {
        shell.dir_stack.push(PathBuf::from(d));
    } else if let Some(home) = shell.get_env("HOME") {
        shell.dir_stack.push(PathBuf::from(home));
    }
    BuiltinResult::Success
}

fn builtin_popd(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) {
        println!("nsh: popd: popd 0.4.2\nPopd command.\n\nUSAGE:\n    popd\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information");
        return BuiltinResult::Success;
