                    'n' => { res.push('\n'); chars.next(); }
                    't' => { res.push('\t'); chars.next(); }
                    'r' => { res.push('\r'); chars.next(); }
                    '\\' => { res.push('\\'); chars.next(); }
                    'a' => { res.push('\x07'); chars.next(); }
                    'b' => { res.push('\x08'); chars.next(); }
                    'f' => { res.push('\x0c'); chars.next(); }
                    'v' => { res.push('\x0b'); chars.next(); }
                    'e' => { res.push('\x1b'); chars.next(); }
                    _ => { res.push('\\'); }
                }
            } else {
                res.push('\\');
            }
        } else {
            res.push(c);
        }
    }
    res
}

fn builtin_exit(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.is_empty() {
        return BuiltinResult::Exit(shell.last_status);
    }
    if args.len() > 1 {
        return BuiltinResult::Error(1);
    }
    match args[0].parse::<i32>() {
        Ok(code) => BuiltinResult::Exit((code % 256 + 256) % 256),
        Err(_) => BuiltinResult::Error(1),
    }
}

fn builtin_export(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.is_empty() {
        return BuiltinResult::Success;
    }
    for arg in args {
        if let Some((k, v)) = arg.split_once('=') {
            shell.set_env(k, v);
            env::set_var(k, v);
        } else {
            if let Some(v) = shell.get_var(arg) {
                env::set_var(arg, v);
            }
            shell.export_var(arg);
        }
    }
    BuiltinResult::Success
}

fn builtin_unset(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) {
        println!("nsh: unset: unset 0.4.2\nSet command.\n\nUSAGE:\n    unset <NAME>\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nARGS:\n    <NAME>    ");
        return BuiltinResult::Success;
    }
    if args.contains(&"-V".to_string()) || args.contains(&"--version".to_string()) {
        println!("unset 0.4.2");
        return BuiltinResult::Success;
    }
    if args.is_empty() {
        eprintln!("nsh: unset: error: The following required arguments were not provided:\n    <NAME>\n\nUSAGE:\n    unset <NAME>\n\nFor more information try --help");
        return BuiltinResult::Error(1);
    }
    for arg in args {
        shell.unset_var(arg);
        env::remove_var(arg);
    }
    BuiltinResult::Success
}

fn builtin_alias(shell: &mut Shell, args: &[String]) -> BuiltinResult {
    if args.is_empty() {
        let mut keys: Vec<&String> = shell.aliases.keys().collect();
        keys.sort();
        for k in keys {
            if let Some(v) = shell.aliases.get(k) {
                println!("{}='{}'", k, v);
            }
        }
        return BuiltinResult::Success;
    }
    for arg in args {
        if let Some((k, v)) = arg.split_once('=') {
            let clean_v = v.trim_matches('\'').trim_matches('"');
            shell.aliases.insert(k.to_string(), clean_v.to_string());
        } else {
            eprintln!("nsh: alias:  --> 1:1\n  |\n1 | {}\n  | ^---\n  |\n  = expected alias", arg);
            return BuiltinResult::Error(1);
        }
    }
    BuiltinResult::Success
}

fn builtin_jobs(shell: &mut Shell, args: &[String]) -> BuiltinResult {
