use std::env;
use std::path::Path;

pub fn expand_prompt(prompt_pattern: &str) -> String {
    let mut s = prompt_pattern.to_string();

    // 1. Handle \if{cond}{then}{else}
    while let Some(if_idx) = s.find("\\if{") {
        if let Some(rest) = parse_ternary(&s[if_idx..]) {
            let (cond, then_str, else_str, total_len) = rest;
            let is_true = match cond.as_str() {
                "in_remote" => env::var("SSH_CLIENT").is_ok(),
                "in_repo" => git2::Repository::discover(".").is_ok(),
                _ => false,
            };
            let replacement = if is_true { then_str } else { else_str };
            s.replace_range(if_idx..if_idx + total_len, &replacement);
        } else {
            break;
        }
    }

    // 2. Expand values & text styles
    let username = env::var("USER").unwrap_or_else(|_| "user".to_string());
    let hostname = get_hostname();
    let current_dir = get_current_dir();
    let repo_status = get_repo_status();

    s = s.replace("\\{username}", &username);
    s = s.replace("\\{hostname}", &hostname);
    s = s.replace("\\{current_dir}", &current_dir);
    s = s.replace("\\{repo_status}", &repo_status);

    s = s.replace("\\{reset}", "\x1b[0m");
    s = s.replace("\\{bold}", "\x1b[1m");
    s = s.replace("\\{underline}", "\x1b[4m");
    s = s.replace("\\{red}", "\x1b[31m");
    s = s.replace("\\{green}", "\x1b[32m");
    s = s.replace("\\{yellow}", "\x1b[33m");
    s = s.replace("\\{blue}", "\x1b[34m");
    s = s.replace("\\{magenta}", "\x1b[35m");
    s = s.replace("\\{cyan}", "\x1b[36m");
    s = s.replace("\\n", "\n");

    s
}

fn parse_ternary(s: &str) -> Option<(String, String, String, usize)> {
    // s starts with "\if{"
    let s_after = &s[4..]; // after "\if{"
    let cond_end = s_after.find('}')?;
    let cond = s_after[..cond_end].to_string();

    let s_then = &s_after[cond_end + 1..];
    if !s_then.starts_with('{') {
        return None;
    }
    let then_end = find_matching_brace(&s_then[1..])?;
    let then_str = s_then[1..1 + then_end].to_string();

    let s_else = &s_then[1 + then_end + 1..];
    if !s_else.starts_with('{') {
        return None;
    }
    let else_end = find_matching_brace(&s_else[1..])?;
    let else_str = s_else[1..1 + else_end].to_string();

    let total_len = 4 + cond_end + 1 + 1 + then_end + 1 + 1 + else_end + 1;
    Some((cond, then_str, else_str, total_len))
}

fn find_matching_brace(s: &str) -> Option<usize> {
    let mut depth = 1;
    for (i, c) in s.char_indices() {
        if c == '{' {
            depth += 1;
        } else if c == '}' {
            depth -= 1;
            if depth == 0 {
                return Some(i);
            }
        }
    }
    None
}

fn get_hostname() -> String {
    let mut buf = vec![0u8; 256];
    unsafe {
        if libc::gethostname(buf.as_mut_ptr() as *mut libc::c_char, buf.len()) == 0 {
            if let Ok(s) = std::ffi::CStr::from_ptr(buf.as_ptr() as *const libc::c_char).to_str() {
                return s.to_string();
            }
        }
    }
    "localhost".to_string()
}

fn get_current_dir() -> String {
    if let Ok(cwd) = env::current_dir() {
        let cwd_str = cwd.to_string_lossy().to_string();
        if let Ok(home) = env::var("HOME") {
            if cwd_str == home {
                return "~".to_string();
            } else if cwd_str.starts_with(&format!("{}/", home)) {
                return format!("~{}", &cwd_str[home.len()..]);
            }
        }
        return cwd_str;
    }
    ".".to_string()
}

fn get_repo_status() -> String {
    if let Ok(repo) = git2::Repository::discover(".") {
        let branch = if let Ok(head) = repo.head() {
            if head.is_branch() {
                head.shorthand().unwrap_or("HEAD").to_string()
            } else {
                "HEAD".to_string()
            }
        } else {
            "HEAD".to_string()
        };

        let mut is_dirty = false;
        if let Ok(statuses) = repo.statuses(Some(git2::StatusOptions::new().include_untracked(true))) {
            if !statuses.is_empty() {
                is_dirty = true;
            }
        }

        if is_dirty {
            format!("{}*", branch)
        } else {
            branch
        }
    } else {
        "".to_string()
    }
}
EOF"}

