use std::io::{BufRead, BufReader, Write};
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};

pub struct Completer {
    child: Option<Child>,
    stdin: Option<ChildStdin>,
    stdout: Option<BufReader<ChildStdout>>,
}

impl Completer {
    pub fn new() -> Self {
        let mut child = match Command::new("bash")
            .arg("--noprofile")
            .arg("--norc")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::null())
            .spawn()
        {
            Ok(c) => c,
            Err(_) => return Self { child: None, stdin: None, stdout: None },
        };

        let stdin = child.stdin.take();
        let stdout = child.stdout.take().map(BufReader::new);

        let mut completer = Self {
            child: Some(child),
            stdin,
            stdout,
        };

        completer.init_bash();
        completer
    }

    fn init_bash(&mut self) {
        let setup_cmd = r#"
for d in /usr/local/etc/bash_completion.d /usr/etc/bash_completion.d /etc/bash_completion.d; do
    if [ -d "$d" ]; then
        for f in "$d"/*; do
            [ -f "$f" ] && . "$f" 2>/dev/null
        done
    fi
done
"#;
        self.send_cmd(setup_cmd);
    }

    fn send_cmd(&mut self, cmd: &str) {
        if let Some(stdin) = self.stdin.as_mut() {
            let _ = stdin.write_all(cmd.as_bytes());
            let _ = stdin.flush();
        }
    }

    pub fn complete(&mut self, line: &str) -> Vec<String> {
        if self.stdin.is_none() || self.stdout.is_none() {
            return Vec::new();
        }

        let words: Vec<&str> = line.split_whitespace().collect();
        let is_command = words.len() <= 1 && !line.ends_with(' ');
        let last_word = if line.ends_with(' ') {
            ""
        } else {
            words.last().copied().unwrap_or("")
        };

        let query_cmd = if is_command {
            format!(
                "compgen -c '{}' | sort -u; echo '---END---'\n",
                last_word.replace('\'', "'\\''")
            )
        } else {
            format!(
                "compgen -f '{}' | sort -u; echo '---END---'\n",
                last_word.replace('\'', "'\\''")
            )
        };

        self.send_cmd(&query_cmd);

        let mut results = Vec::new();
        if let Some(stdout) = self.stdout.as_mut() {
            let mut buf = String::new();
            while stdout.read_line(&mut buf).is_ok() {
                let trimmed = buf.trim_end_matches(&['\r', '\n'][..]);
                if trimmed == "---END---" {
                    break;
                }
                if !trimmed.is_empty() {
                    results.push(trimmed.to_string());
                }
                buf.clear();
            }
        }
        results
    }
}

impl Drop for Completer {
    fn drop(&mut self) {
        if let Some(mut child) = self.child.take() {
            let _ = child.kill();
        }
    }
}
EOF"}

