    pub fn new() -> Self {
        let mut env_map = HashMap::new();
        let mut exported_set = HashSet::new();
        for (k, v) in env::vars() {
            env_map.insert(k.clone(), v);
            exported_set.insert(k);
        }

        let home = env::var("HOME").unwrap_or_else(|_| "/tmp".to_string());
        let history_file = PathBuf::from(&home).join(".nsh_history");

        let mut shell = Self {
            env: env_map,
            vars: HashMap::new(),
            exported: exported_set,
            aliases: HashMap::new(),
            functions: HashMap::new(),
            dir_stack: Vec::new(),
            last_status: 0,
            last_bg_pid: None,
            jobs: Vec::new(),
            flag_e: false,
            flag_u: false,
            flag_n: false,
            history: Vec::new(),
            history_file,
            positional_args: Vec::new(),
            stashed_line: None,
        };

        shell.load_history();
        shell
    }

    pub fn get_var(&self, name: &str) -> Option<String> {
        match name {
            "?" => Some(self.last_status.to_string()),
            "!" => Some(self.last_bg_pid.map(|p| p.to_string()).unwrap_or_default()),
            "#" => Some(self.positional_args.len().to_string()),
            "$" => Some(std::process::id().to_string()),
            "0" => Some(self.positional_args.first().cloned().unwrap_or_default()),
            "@" | "*" => Some(self.positional_args.join(" ")),
            _ => {
                if let Ok(idx) = name.parse::<usize>() {
                    if idx > 0 && idx <= self.positional_args.len() {
                        return Some(self.positional_args[idx - 1].clone());
                    }
                }
                if let Some(v) = self.vars.get(name) {
                    return Some(v.clone());
                }
                if let Some(v) = self.env.get(name) {
                    return Some(v.clone());
                }
                if let Ok(v) = env::var(name) {
                    return Some(v);
                }
                None
            }
        }
    }

    pub fn get_env(&self, name: &str) -> Option<String> {
        self.env.get(name).cloned().or_else(|| env::var(name).ok())
    }

    pub fn set_var(&mut self, name: &str, val: &str) {
        if self.exported.contains(name) {
            self.env.insert(name.to_string(), val.to_string());
            env::set_var(name, val);
        } else {
            self.vars.insert(name.to_string(), val.to_string());
        }
    }

    pub fn set_env(&mut self, name: &str, val: &str) {
        self.env.insert(name.to_string(), val.to_string());
        self.exported.insert(name.to_string());
        env::set_var(name, val);
    }

