            } else if chars.peek() == Some(&'{') {
                chars.next(); // consume '{'
                let mut expr = String::new();
                while let Some(ch) = chars.next() {
                    if ch == '}' {
                        break;
                    }
                    expr.push(ch);
                }
                let val = eval_param_expansion(shell, &expr);
                result.push_str(&val);
            } else {
                let mut var_name = String::new();
                if let Some(&next_c) = chars.peek() {
                    if matches!(next_c, '?' | '!' | '#' | '$' | '0'..='9' | '*' | '@') {
                        var_name.push(chars.next().unwrap());
                    } else {
                        while let Some(&ch) = chars.peek() {
                            if ch.is_alphanumeric() || ch == '_' {
                                var_name.push(chars.next().unwrap());
                            } else {
                                break;
                            }
                        }
                    }
                }
                if var_name.is_empty() {
                    result.push('$');
                } else {
                    if shell.flag_u && shell.get_var(&var_name).is_none() {
                        eprintln!("nsh: undefined variable `{}`", var_name);
                        shell.last_status = 1;
                    } else {
                        let val = shell.get_var(&var_name).unwrap_or_default();
                        result.push_str(&val);
                    }
                }
            }
        } else if c == '`' {
            let mut cmd_str = String::new();
            while let Some(ch) = chars.next() {
                if ch == '`' {
                    break;
                }
                cmd_str.push(ch);
            }
            let val = run_cmd_subst(shell, &cmd_str);
            result.push_str(&val);
        } else {
            result.push(c);
        }
    }

    result
}

fn eval_param_expansion(shell: &mut Shell, expr: &str) -> String {
    if expr.starts_with('#') {
        let var_name = &expr[1..];
        let val = shell.get_var(var_name).unwrap_or_default();
        return val.len().to_string();
    }

    if let Some((var, rest)) = expr.split_once("//") {
        let val = shell.get_var(var).unwrap_or_default();
        if let Some((pat, rep)) = rest.split_once('/') {
            return val.replace(pat, rep);
        }
        return val;
    }

    if let Some((var, rest)) = expr.split_once('/') {
        let val = shell.get_var(var).unwrap_or_default();
        if let Some((pat, rep)) = rest.split_once('/') {
            if let Some(pos) = val.find(pat) {
                let mut res = val.clone();
                res.replace_range(pos..pos + pat.len(), rep);
                return res;
            }
        }
        return val;
    }

    if let Some((var, default)) = expr.split_once(":-") {
        let val = shell.get_var(var).unwrap_or_default();
        if val.is_empty() {
            return default.to_string();
        }
        return val;
    }

    if let Some((var, default)) = expr.split_once("-") {
        match shell.get_var(var) {
            Some(v) => v,
            None => default.to_string(),
        }
    } else if let Some((var, default)) = expr.split_once(":=") {
        let val = shell.get_var(var).unwrap_or_default();
        if val.is_empty() {
            shell.set_var(var, default);
            return default.to_string();
        }
        val
    } else if let Some((var, default)) = expr.split_once("=") {
        match shell.get_var(var) {
            Some(v) => v,
            None => {
                shell.set_var(var, default);
                default.to_string()
            }
        }
    } else {
        if shell.flag_u && shell.get_var(expr).is_none() {
            eprintln!("nsh: undefined variable `{}`", expr);
            shell.last_status = 1;
            String::new()
        } else {
            shell.get_var(expr).unwrap_or_default()
        }
    }
}

fn run_cmd_subst(shell: &mut Shell, cmd: &str) -> String {
    use std::process::{Command, Stdio};
    let mut child = match Command::new("/bin/sh")
        .arg("-c")
        .arg(cmd)
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
    {
        Ok(c) => c,
        Err(_) => return String::new(),
    };

    use std::io::Read;
    let mut out = String::new();
    if let Some(mut stdout) = child.stdout.take() {
        let _ = stdout.read_to_string(&mut out);
    }
    let _ = child.wait();
    out.trim_end_matches(&['\r', '\n'][..]).to_string()
}

fn eval_arithmetic(shell: &mut Shell, expr: &str) -> i64 {
    let expanded = expand_vars_subst(shell, expr);
    eval_arith_expr(&expanded)
}

fn eval_arith_expr(expr: &str) -> i64 {
    // Simple arithmetic expression evaluator for +, -, *, /, %, (), numbers
    let expr = expr.trim();
    if expr.is_empty() {
        return 0;
    }

    // Basic shunting yard / recursive descent
    let tokens = tokenize_arith(expr);
    parse_arith_tokens(&tokens)
}

fn tokenize_arith(expr: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut chars = expr.chars().peekable();

    while let Some(&c) = chars.peek() {
        if c.is_whitespace() {
            chars.next();
        } else if c.is_ascii_digit() {
            let mut num = String::new();
            while let Some(&ch) = chars.peek() {
                if ch.is_ascii_digit() {
                    num.push(chars.next().unwrap());
                } else {
                    break;
                }
            }
            tokens.push(num);
        } else if "+-*/%()".contains(c) {
            tokens.push(chars.next().unwrap().to_string());
        } else if c.is_alphabetic() || c == '_' {
            let mut ident = String::new();
            while let Some(&ch) = chars.peek() {
                if ch.is_alphanumeric() || ch == '_' {
                    ident.push(chars.next().unwrap());
                } else {
                    break;
                }
            }
            tokens.push(ident);
        } else {
            chars.next();
        }
    }
    tokens
}

fn parse_arith_tokens(tokens: &[String]) -> i64 {
    let mut idx = 0;
    parse_expr_assoc(tokens, &mut idx, 0)
}

fn parse_expr_assoc(tokens: &[String], idx: &mut usize, min_prec: u8) -> i64 {
    let mut lhs = parse_atom(tokens, idx);

    while *idx < tokens.len() {
        let op = &tokens[*idx];
        let prec = match op.as_str() {
            "+" | "-" => 1,
            "*" | "/" | "%" => 2,
            _ => break,
        };

        if prec < min_prec {
            break;
        }

        *idx += 1; // consume op
        let rhs = parse_expr_assoc(tokens, idx, prec + 1);

        lhs = match op.as_str() {
            "+" => lhs + rhs,
            "-" => lhs - rhs,
            "*" => lhs * rhs,
            "/" => if rhs != 0 { lhs / rhs } else { 0 },
            "%" => if rhs != 0 { lhs % rhs } else { 0 },
            _ => lhs,
        };
    }

    lhs
}

fn parse_atom(tokens: &[String], idx: &mut usize) -> i64 {
    if *idx >= tokens.len() {
        return 0;
    }
    let tok = &tokens[*idx];
    if tok == "(" {
        *idx += 1;
        let val = parse_expr_assoc(tokens, idx, 0);
        if *idx < tokens.len() && tokens[*idx] == ")" {
            *idx += 1;
        }
        val
    } else if tok == "-" {
        *idx += 1;
        -parse_atom(tokens, idx)
    } else if tok == "+" {
        *idx += 1;
        parse_atom(tokens, idx)
    } else {
        *idx += 1;
        tok.parse::<i64>().unwrap_or(0)
    }
}
EOF"}

