use std::env;
use std::ffi::CString;
use std::fs::File;
use std::os::unix::ffi::OsStrExt;
use std::os::unix::io::{AsRawFd, FromRawFd, IntoRawFd, RawFd};
use std::path::{Path, PathBuf};

use crate::builtins::{run_builtin, is_builtin, BuiltinResult};
use crate::parser::{Command, Redirect, SimpleCommand};
use crate::shell::Shell;

pub fn execute_simple_command(shell: &mut Shell, cmd: &SimpleCommand) -> i32 {
    if cmd.words.is_empty() {
        // Variable assignments only
        for (k, v) in &cmd.env_assignments {
            let expanded_v = crate::expand::expand_word(shell, v).join(" ");
            shell.set_var(k, &expanded_v);
        }
        return 0;
    }

    let mut expanded_words = Vec::new();
    for w in &cmd.words {
        let ex = crate::expand::expand_word(shell, w);
        expanded_words.extend(ex);
    }

    if expanded_words.is_empty() {
        return 0;
    }

    // Check alias
    let first_word = &expanded_words[0];
    if let Some(alias_val) = shell.aliases.get(first_word).cloned() {
        let mut new_script = alias_val;
        if expanded_words.len() > 1 {
            new_script.push(' ');
            new_script.push_str(&expanded_words[1..].join(" "));
        }
        return shell.eval_script(&new_script) as i32;
    }

    // Check function
    if let Some(fn_body) = shell.functions.get(first_word).cloned() {
        let old_pos = shell.positional_args.clone();
        shell.positional_args = expanded_words[1..].to_vec();
        let res = shell.eval_script(&fn_body);
        shell.positional_args = old_pos;
        return match res {
            BuiltinResult::Success => 0,
            BuiltinResult::Exit(c) | BuiltinResult::Error(c) => c,
        };
    }

    // Check builtin
    if is_builtin(first_word) {
        // Temporary environment assignments
        for (k, v) in &cmd.env_assignments {
            let expanded_v = crate::expand::expand_word(shell, v).join(" ");
            shell.set_var(k, &expanded_v);
        }
        return match run_builtin(shell, &expanded_words) {
            BuiltinResult::Success => 0,
            BuiltinResult::Exit(c) | BuiltinResult::Error(c) => c,
        };
    }

    // External executable
    execute_external(shell, &expanded_words, &cmd.env_assignments, &cmd.redirections)
}

fn resolve_binary(cmd: &str) -> Option<PathBuf> {
    if cmd.contains('/') {
        let p = PathBuf::from(cmd);
        if p.exists() {
            return Some(p);
        }
        return None;
    }

    if let Ok(path_env) = env::var("PATH") {
        for dir in path_env.split(':') {
            let p = Path::new(dir).join(cmd);
            if p.exists() {
                return Some(p);
            }
        }
    }
    None
}

fn execute_external(
    shell: &mut Shell,
    args: &[String],
    env_assigns: &[(String, String)],
    redirections: &[Redirect],
) -> i32 {
    let cmd_name = &args[0];
    let resolved = match resolve_binary(cmd_name) {
        Some(p) => p,
        None => {
            eprintln!("nsh: command not found `{}`", cmd_name);
            return 1;
        }
    };

    // Check if executable
    use std::os::unix::fs::PermissionsExt;
    if let Ok(metadata) = std::fs::metadata(&resolved) {
        if metadata.is_dir() || (metadata.permissions().mode() & 0o111) == 0 {
            eprintln!(
                "nsh: Failed to exec \"{}\" (EACCESS). chmod(1) may help.",
                resolved.to_string_lossy()
            );
            return 1;
        }
    }

