{"command":"cat << 'EOF' > src/eval.rs
use crate::builtins::{run_builtin, BuiltinResult};
use crate::parser::*;
use crate::process::execute_simple_command;
use crate::shell::Shell;

pub fn eval_script(shell: &mut Shell, script_str: &str) -> BuiltinResult {
    let script = match parse_script(script_str) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("nsh: parse error: {}", e);
            return BuiltinResult::Error(255);
        }
    };

    if shell.flag_n {
        return BuiltinResult::Success;
    }

    eval_parsed_script(shell, &script)
}

pub fn eval_parsed_script(shell: &mut Shell, script: &Script) -> BuiltinResult {
    let mut last_res = BuiltinResult::Success;

    for item in &script.items {
        last_res = eval_and_or_list(shell, item);

        if let BuiltinResult::Exit(_) = last_res {
            return last_res;
        }

        if shell.flag_e && shell.last_status != 0 {
            return BuiltinResult::Error(shell.last_status);
        }
    }

    last_res
}

fn eval_and_or_list(shell: &mut Shell, list: &AndOrList) -> BuiltinResult {
    let mut status = eval_pipeline(shell, &list.first);

    for (op, next_pipe) in &list.rest {
        match op {
            AndOrOp::And => {
                if status == 0 {
                    status = eval_pipeline(shell, next_pipe);
                }
            }
            AndOrOp::Or => {
                if status != 0 {
                    status = eval_pipeline(shell, next_pipe);
                }
            }
        }
    }

    shell.last_status = status;
    if status == 0 {
        BuiltinResult::Success
    } else {
        BuiltinResult::Error(status)
    }
}

fn eval_pipeline(shell: &mut Shell, pipeline: &Pipeline) -> i32 {
    if pipeline.commands.is_empty() {
        return 0;
    }

    if pipeline.commands.len() == 1 {
        if pipeline.background {
            // Run command in background
            let cmd = &pipeline.commands[0];
            let cmd_str = format!("{:?}", cmd);
            unsafe {
                let pid = libc::fork();
                if pid == 0 {
                    let status = eval_command(shell, cmd);
                    libc::_exit(status);
                } else if pid > 0 {
                    shell.add_job(pid as u32, cmd_str);
                    return 0;
                }
            }
            return 0;
        } else {
            return eval_command(shell, &pipeline.commands[0]);
        }
    }

    // Multiple commands in pipeline
    let mut fds = vec![0; (pipeline.commands.len() - 1) * 2];
    for i in 0..pipeline.commands.len() - 1 {
        unsafe {
            libc::pipe(fds[i * 2..i * 2 + 2].as_mut_ptr());
        }
    }

    let mut pids = Vec::new();
    for (i, cmd) in pipeline.commands.iter().enumerate() {
        unsafe {
            let pid = libc::fork();
            if pid == 0 {
                // Connect stdin
                if i > 0 {
                    libc::dup2(fds[(i - 1) * 2], libc::STDIN_FILENO);
                }
                // Connect stdout
                if i < pipeline.commands.len() - 1 {
                    libc::dup2(fds[i * 2 + 1], libc::STDOUT_FILENO);
                }

                // Close all pipe fds
                for fd in &fds {
                    libc::close(*fd);
                }

                let status = eval_command(shell, cmd);
                libc::_exit(status);
            } else if pid > 0 {
                pids.push(pid);
            }
        }
    }

    // Close pipe fds in parent
    for fd in &fds {
        unsafe {
            libc::close(*fd);
        }
    }

    let mut last_status = 0;
    if pipeline.background {
        let cmd_str = "pipeline".to_string();
        if let Some(&last_pid) = pids.last() {
            shell.add_job(last_pid as u32, cmd_str);
        }
    } else {
        for pid in pids {
            let mut status = 0;
            unsafe {
                libc::waitpid(pid, &mut status, 0);
            }
            if libc::WIFEXITED(status) {
                last_status = libc::WEXITSTATUS(status);
            } else if libc::WIFSIGNALED(status) {
                last_status = 128 + libc::WTERMSIG(status);
            }
        }
    }

    last_status
}

fn eval_command(shell: &mut Shell, cmd: &Command) -> i32 {
    match cmd {
        Command::Simple(sc) => execute_simple_command(shell, sc),
        Command::If(stmt) => eval_if(shell, stmt),
        Command::While(stmt) => eval_while(shell, stmt),
        Command::For(stmt) => eval_for(shell, stmt),
        Command::Case(stmt) => eval_case(shell, stmt),
        Command::Function(fn_def) => {
            shell.functions.insert(fn_def.name.clone(), format!("{:?}", fn_def.body));
            0
        }
        Command::Local(name, val) => {
            let expanded_val = val
                .as_ref()
                .map(|v| crate::expand::expand_word(shell, v).join(" "))
                .unwrap_or_default();
            shell.vars.insert(name.clone(), expanded_val);
            0
        }
        Command::Break => 0,
        Command::Continue => 0,
        Command::Subshell(sub) => {
            unsafe {
                let pid = libc::fork();
                if pid == 0 {
                    let res = eval_parsed_script(shell, sub);
                    let code = match res {
                        BuiltinResult::Success => 0,
                        BuiltinResult::Exit(c) | BuiltinResult::Error(c) => c,
                    };
                    libc::_exit(code);
                } else {
                    let mut status = 0;
                    libc::waitpid(pid, &mut status, 0);
                    if libc::WIFEXITED(status) {
                        return libc::WEXITSTATUS(status);
                    }
                    return 1;
                }
            }
        }
        Command::Block(blk) => {
            let res = eval_parsed_script(shell, blk);
            match res {
                BuiltinResult::Success => 0,
                BuiltinResult::Exit(c) | BuiltinResult::Error(c) => c,
            }
        }
    }
}

fn eval_if(shell: &mut Shell, stmt: &IfStmt) -> i32 {
    eval_parsed_script(shell, &stmt.cond);
    if shell.last_status == 0 {
        let res = eval_parsed_script(shell, &stmt.then_body);
        return match res {
            BuiltinResult::Success => 0,
            BuiltinResult::Exit(c) | BuiltinResult::Error(c) => c,
        };
    }

    for (elif_cond, elif_body) in &stmt.elifs {
        eval_parsed_script(shell, elif_cond);
        if shell.last_status == 0 {
            let res = eval_parsed_script(shell, elif_body);
            return match res {
                BuiltinResult::Success => 0,
                BuiltinResult::Exit(c) | BuiltinResult::Error(c) => c,
            };
        }
    }

    if let Some(else_body) = &stmt.else_body {
        let res = eval_parsed_script(shell, else_body);
        return match res {
            BuiltinResult::Success => 0,
            BuiltinResult::Exit(c) | BuiltinResult::Error(c) => c,
        };
    }

    0
}

fn eval_while(shell: &mut Shell, stmt: &WhileStmt) -> i32 {
    let mut status = 0;
    loop {
        eval_parsed_script(shell, &stmt.cond);
        if shell.last_status != 0 {
            break;
        }
        let res = eval_parsed_script(shell, &stmt.body);
