    let mut status = eval_pipeline(shell, &list.first);

    for (op, next_pipe) in &list.rest {
        match op {
            AndOrOp::And => {
                if status == 0 {
                    status = eval_pipeline(shell, next_pipe);
                }
            }
            AndOrOp::Or => {
                if status != 0 {
                    status = eval_pipeline(shell, next_pipe);
                }
            }
        }
    }

    shell.last_status = status;
    if status == 0 {
        BuiltinResult::Success
    } else {
        BuiltinResult::Error(status)
    }
