use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader, Write};
use std::panic;
use std::path::{Path, PathBuf};

use crate::shell::Shell;

fn main() {
    setup_panic_hook_and_logger();

    let args: Vec<String> = env::args().collect();
    let bin_name = args.first().cloned().unwrap_or_else(|| "executable".to_string());

    let mut command_opt: Option<String> = None;
    let mut login_opt = false;
    let mut norc_opt = false;
    let mut version_opt = false;
    let mut help_opt = false;
    let mut file_opt: Option<String> = None;

    let mut idx = 1;
    while idx < args.len() {
        let arg = &args[idx];
        match arg.as_str() {
            "-c" => {
                if idx + 1 < args.len() {
                    command_opt = Some(args[idx + 1].clone());
                    idx += 2;
                } else {
                    eprintln!("error: The argument '-c <command>' requires a value but none was supplied\n\nUSAGE:\n    {} -c <command>\n\nFor more information try --help", bin_name);
                    std::process::exit(1);
                }
            }
            "-l" | "--login" => {
                login_opt = true;
                idx += 1;
            }
            "--norc" => {
                norc_opt = true;
                idx += 1;
            }
            "--version" => {
                version_opt = true;
                idx += 1;
            }
            "-h" | "--help" => {
                help_opt = true;
                idx += 1;
            }
            _ => {
                if arg.starts_with('-') {
                    eprintln!(
                        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {} [FLAGS] [OPTIONS] [FILE]\n\nFor more information try --help",
                        arg, bin_name
                    );
                    std::process::exit(1);
                } else if file_opt.is_none() && command_opt.is_none() {
                    file_opt = Some(arg.clone());
                    idx += 1;
                } else {
                    eprintln!(
                        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {} [FLAGS] [OPTIONS] [FILE]\n\nFor more information try --help",
                        arg, bin_name
                    );
                    std::process::exit(1);
                }
            }
        }
    }

    if version_opt {
        println!("0.4.2");
        return;
    }

    if help_opt {
        println!(
            "nsh 0.4.2\nA command-line shell that focuses on performance and productivity.\n\nUSAGE:\n    {} [FLAGS] [OPTIONS] [FILE]\n\nFLAGS:\n    -h, --help       Prints help information\n    -l, --login      Behave like a login shell\n        --norc       Don't load nshrc\n        --version    Print the version\n\nOPTIONS:\n    -c <command>        The command to be executed\n\nARGS:\n    <FILE>    The file to be executed",
            bin_name
        );
        return;
    }

    let mut shell = Shell::new();

    // Load .nshrc unless --norc is set
    if !norc_opt {
        load_rc(&mut shell);
    }

    if let Some(cmd_str) = command_opt {
        let res = shell.eval_script(&cmd_str);
        let code = match res {
            builtins::BuiltinResult::Success => 0,
            builtins::BuiltinResult::Exit(c) | builtins::BuiltinResult::Error(c) => c,
        };
        std::process::exit(code);
    } else if let Some(script_file) = file_opt {
        match std::fs::read_to_string(&script_file) {
            Ok(content) => {
                let res = shell.eval_script(&content);
                let code = match res {
                    builtins::BuiltinResult::Success => 0,
                    builtins::BuiltinResult::Exit(c) | builtins::BuiltinResult::Error(c) => c,
                };
                std::process::exit(code);
            }
            Err(e) => {
                eprintln!("nsh: {}: {}", script_file, e);
                std::process::exit(1);
            }
        }
    } else {
        use crossterm::tty::IsTty;
        let stdin_tty = std::io::stdin().is_tty();
        let stdout_tty = std::io::stdout().is_tty();

        if !stdout_tty {
            eprintln!("nsh: warning: stdout is not a tty");
        }

        if !stdin_tty {
            let mut input = String::new();
            let mut reader = BufReader::new(std::io::stdin());
            let mut code = 0;
            while reader.read_line(&mut input).unwrap_or(0) > 0 {
                let res = shell.eval_script(&input);
                code = match res {
                    builtins::BuiltinResult::Success => 0,
                    builtins::BuiltinResult::Exit(c) | builtins::BuiltinResult::Error(c) => c,
                };
                input.clear();
            }
            std::process::exit(code);
        } else {
            mainloop::run_interactive_loop(&mut shell);
        }
    }
}

fn load_rc(shell: &mut Shell) {
    let rc_path = if let Ok(xdg) = env::var("XDG_CONFIG_HOME") {
        let p = PathBuf::from(xdg).join("nsh/nshrc");
        if p.exists() {
            Some(p)
        } else {
            None
        }
    } else {
        None
    };

    let rc_path = rc_path.or_else(|| {
        if let Ok(home) = env::var("HOME") {
            let p = PathBuf::from(home).join(".nshrc");
            if p.exists() {
                Some(p)
            } else {
                None
            }
        } else {
            None
        }
    });

    if let Some(p) = rc_path {
        if let Ok(content) = std::fs::read_to_string(&p) {
            shell.eval_script(&content);
        }
    }
}

fn setup_panic_hook_and_logger() {
    let home = env::var("HOME").unwrap_or_else(|_| "/tmp".to_string());
    let log_path = PathBuf::from(&home).join(".nsh.log");

    panic::set_hook(Box::new(move |info| {
        let location = info
            .location()
            .map(|l| format!("{}:{}:{}", l.file(), l.line(), l.column()))
            .unwrap_or_else(|| "unknown".to_string());
        let msg = match info.payload().downcast_ref::<&str>() {
            Some(s) => (*s).to_string(),
            None => match info.payload().downcast_ref::<String>() {
                Some(s) => s.clone(),
                None => "Box<Any>".to_string(),
            },
        };

        let log_msg = format!(
            "\x1b[1m[\x1b[31mERROR\x1b[0m\t]\x1b[0m \x1b[36msrc/main.rs\x1b[0m: panicked at {}:\n{}\n",
            location, msg
        );

        if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(&log_path) {
            let _ = f.write_all(log_msg.as_bytes());
        }

        eprintln!(
            "\x1b[1m\x1b[38;5;11mnsh: panicked at {}:\n{}\x1b[0m\n\x1b[1m\x1b[38;5;11mnsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues\x1b[0m",
            location, msg
        );
    }));
}
EOF"}

