use std::env;
use std::fs;
use std::path::Path;

use crate::shell::Shell;

pub fn expand_word(shell: &mut Shell, word: &str) -> Vec<String> {
    if word.is_empty() {
        return vec![String::new()];
    }

    // Tilde expansion
    let word = if word == "~" {
        shell.get_env("HOME").unwrap_or_else(|| "/".to_string())
    } else if word.starts_with("~/") {
        let home = shell.get_env("HOME").unwrap_or_else(|| "/".to_string());
        format!("{}/{}", home, &word[2..])
    } else {
        word.to_string()
    };

    // Variable, command substitution, arithmetic expansion
    let expanded = expand_vars_subst(shell, &word);

    // Globbing
    if expanded.contains('*') || expanded.contains('?') {
        let (dir_part, pattern_part) = if let Some(last_slash) = expanded.rfind('/') {
            (&expanded[..last_slash + 1], &expanded[last_slash + 1..])
        } else {
            ("", expanded.as_str())
        };

        let search_dir = if dir_part.is_empty() { "." } else { dir_part };
        if let Ok(entries) = fs::read_dir(search_dir) {
            let mut matches = Vec::new();
            for entry in entries.flatten() {
                let name = entry.file_name().to_string_lossy().to_string();
                if glob_match(pattern_part, &name) {
                    if dir_part.is_empty() {
                        matches.push(name);
                    } else {
                        matches.push(format!("{}{}", dir_part, name));
                    }
                }
            }
            if !matches.is_empty() {
                matches.sort();
                return matches;
            }
        }
    }

    vec![expanded]
}

pub fn glob_match(pattern: &str, text: &str) -> bool {
    if pattern == "*" {
        return true;
    }
    let p_chars: Vec<char> = pattern.chars().collect();
    let t_chars: Vec<char> = text.chars().collect();
    let mut px = 0;
    let mut tx = 0;
    let mut star_px = None;
    let mut star_tx = None;

    while tx < t_chars.len() {
        if px < p_chars.len() && (p_chars[px] == '?' || p_chars[px] == t_chars[tx]) {
            px += 1;
            tx += 1;
        } else if px < p_chars.len() && p_chars[px] == '*' {
            star_px = Some(px);
            star_tx = Some(tx);
            px += 1;
        } else if let Some(spx) = star_px {
            px = spx + 1;
            star_tx = Some(star_tx.unwrap() + 1);
            tx = star_tx.unwrap();
        } else {
            return false;
        }
    }

    while px < p_chars.len() && p_chars[px] == '*' {
        px += 1;
    }

    px == p_chars.len()
}

fn expand_vars_subst(shell: &mut Shell, input: &str) -> String {
    let mut result = String::new();
    let mut chars = input.chars().peekable();

    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(next) = chars.next() {
                result.push(next);
            }
        } else if c == '$' {
            if chars.peek() == Some(&'(') {
                chars.next(); // consume '('
                if chars.peek() == Some(&'(') {
                    chars.next(); // consume '('
                    let mut arith_str = String::new();
                    while let Some(ch) = chars.next() {
                        if ch == ')' && chars.peek() == Some(&')') {
                            chars.next(); // consume ')'
                            break;
                        }
                        arith_str.push(ch);
                    }
                    let val = eval_arithmetic(shell, &arith_str);
                    result.push_str(&val.to_string());
                } else {
                    let mut cmd_str = String::new();
                    let mut depth = 1;
                    while let Some(ch) = chars.next() {
                        if ch == '(' {
                            depth += 1;
                        } else if ch == ')' {
                            depth -= 1;
                            if depth == 0 {
                                break;
                            }
                        }
                        cmd_str.push(ch);
                    }
                    let val = run_cmd_subst(shell, &cmd_str);
                    result.push_str(&val);
                }
            } else if chars.peek() == Some(&'{') {
                chars.next(); // consume '{'
                let mut expr = String::new();
                while let Some(ch) = chars.next() {
                    if ch == '}' {
                        break;
                    }
                    expr.push(ch);
                }
                let val = eval_param_expansion(shell, &expr);
                result.push_str(&val);
            } else {
                let mut var_name = String::new();
                if let Some(&next_c) = chars.peek() {
                    if matches!(next_c, '?' | '!' | '#' | '$' | '0'..='9' | '*' | '@') {
                        var_name.push(chars.next().unwrap());
                    } else {
                        while let Some(&ch) = chars.peek() {
                            if ch.is_alphanumeric() || ch == '_' {
                                var_name.push(chars.next().unwrap());
                            } else {
                                break;
                            }
                        }
                    }
                }
                if var_name.is_empty() {
                    result.push('$');
                } else {
                    if shell.flag_u && shell.get_var(&var_name).is_none() {
                        eprintln!("nsh: undefined variable `{}`", var_name);
                        shell.last_status = 1;
                    } else {
                        let val = shell.get_var(&var_name).unwrap_or_default();
                        result.push_str(&val);
                    }
                }
            }
        } else if c == '`' {
            let mut cmd_str = String::new();
            while let Some(ch) = chars.next() {
                if ch == '`' {
                    break;
                }
                cmd_str.push(ch);
            }
            let val = run_cmd_subst(shell, &cmd_str);
            result.push_str(&val);
        } else {
            result.push(c);
        }
    }

    result
}

fn eval_param_expansion(shell: &mut Shell, expr: &str) -> String {
    if expr.starts_with('#') {
        let var_name = &expr[1..];
        let val = shell.get_var(var_name).unwrap_or_default();
        return val.len().to_string();
    }

    if let Some((var, rest)) = expr.split_once("//") {
        let val = shell.get_var(var).unwrap_or_default();
        if let Some((pat, rep)) = rest.split_once('/') {
            return val.replace(pat, rep);
        }
        return val;
    }

    if let Some((var, rest)) = expr.split_once('/') {
        let val = shell.get_var(var).unwrap_or_default();
        if let Some((pat, rep)) = rest.split_once('/') {
            if let Some(pos) = val.find(pat) {
                let mut res = val.clone();
                res.replace_range(pos..pos + pat.len(), rep);
                return res;
            }
        }
        return val;
    }

    if let Some((var, default)) = expr.split_once(":-") {
        let val = shell.get_var(var).unwrap_or_default();
        if val.is_empty() {
            return default.to_string();
        }
        return val;
    }

    if let Some((var, default)) = expr.split_once("-") {
        match shell.get_var(var) {
            Some(v) => v,
            None => default.to_string(),
        }
    } else if let Some((var, default)) = expr.split_once(":=") {
        let val = shell.get_var(var).unwrap_or_default();
        if val.is_empty() {
            shell.set_var(var, default);
            return default.to_string();
        }
        val
    } else if let Some((var, default)) = expr.split_once("=") {
        match shell.get_var(var) {
            Some(v) => v,
            None => {
                shell.set_var(var, default);
                default.to_string()
            }
        }
    } else {
        if shell.flag_u && shell.get_var(expr).is_none() {
            eprintln!("nsh: undefined variable `{}`", expr);
            shell.last_status = 1;
            String::new()
        } else {
            shell.get_var(expr).unwrap_or_default()
        }
    }
}

fn run_cmd_subst(_shell: &mut Shell, cmd: &str) -> String {
    use std::process::{Command, Stdio};
    let mut child = match Command::new("/bin/sh")
        .arg("-c")
        .arg(cmd)
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
    {
        Ok(c) => c,
        Err(_) => return String::new(),
    };

    use std::io::Read;
    let mut out = String::new();
    if let Some(mut stdout) = child.stdout.take() {
        let _ = stdout.read_to_string(&mut out);
    }
    let _ = child.wait();
    out.trim_end_matches(&['\r', '\n'][..]).to_string()
}

fn eval_arithmetic(shell: &mut Shell, expr: &str) -> i64 {
    let expanded = expand_vars_subst(shell, expr);
    eval_arith_expr(&expanded)
}

fn eval_arith_expr(expr: &str) -> i64 {
    let expr = expr.trim();
    if expr.is_empty() {
        return 0;
    }

    let tokens = tokenize_arith(expr);
    parse_arith_tokens(&tokens)
}

fn tokenize_arith(expr: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut chars = expr.chars().peekable();

    while let Some(&c) = chars.peek() {
        if c.is_whitespace() {
            chars.next();
        } else if c.is_ascii_digit() {
            let mut num = String::new();
            while let Some(&ch) = chars.peek() {
                if ch.is_ascii_digit() {
                    num.push(chars.next().unwrap());
                } else {
                    break;
                }
            }
            tokens.push(num);
        } else if "+-*/%()".contains(c) {
            tokens.push(chars.next().unwrap().to_string());
        } else if c.is_alphabetic() || c == '_' {
            let mut ident = String::new();
            while let Some(&ch) = chars.peek() {
                if ch.is_alphanumeric() || ch == '_' {
                    ident.push(chars.next().unwrap());
                } else {
                    break;
                }
            }
            tokens.push(ident);
        } else {
            chars.next();
        }
    }
    tokens
}

fn parse_arith_tokens(tokens: &[String]) -> i64 {
    let mut idx = 0;
    parse_expr_assoc(tokens, &mut idx, 0)
}

fn parse_expr_assoc(tokens: &[String], idx: &mut usize, min_prec: u8) -> i64 {
    let mut lhs = parse_atom(tokens, idx);

    while *idx < tokens.len() {
        let op = &tokens[*idx];
        let prec = match op.as_str() {
            "+" | "-" => 1,
            "*" | "/" | "%" => 2,
            _ => break,
        };

        if prec < min_prec {
            break;
        }

        *idx += 1;
        let rhs = parse_expr_assoc(tokens, idx, prec + 1);

        lhs = match op.as_str() {
            "+" => lhs + rhs,
            "-" => lhs - rhs,
            "*" => lhs * rhs,
            "/" => if rhs != 0 { lhs / rhs } else { 0 },
            "%" => if rhs != 0 { lhs % rhs } else { 0 },
            _ => lhs,
        };
    }

    lhs
}

fn parse_atom(tokens: &[String], idx: &mut usize) -> i64 {
    if *idx >= tokens.len() {
        return 0;
    }
    let tok = &tokens[*idx];
    if tok == "(" {
        *idx += 1;
        let val = parse_expr_assoc(tokens, idx, 0);
        if *idx < tokens.len() && tokens[*idx] == ")" {
            *idx += 1;
        }
        val
    } else if tok == "-" {
        *idx += 1;
        -parse_atom(tokens, idx)
    } else if tok == "+" {
        *idx += 1;
        parse_atom(tokens, idx)
    } else {
        *idx += 1;
        tok.parse::<i64>().unwrap_or(0)
    }
}
