use pest::Parser;
use pest_derive::Parser;

#[derive(Parser)]
#[grammar = "nsh.pest"]
pub struct ShellParser;

#[derive(Debug, Clone)]
pub struct Script {
    pub items: Vec<AndOrList>,
}

#[derive(Debug, Clone)]
pub struct AndOrList {
    pub first: Pipeline,
    pub rest: Vec<(AndOrOp, Pipeline)>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum AndOrOp {
    And,
    Or,
}

#[derive(Debug, Clone)]
pub struct Pipeline {
    pub commands: Vec<Command>,
    pub background: bool,
}

#[derive(Debug, Clone)]
pub enum Command {
    Simple(SimpleCommand),
    If(IfStmt),
    While(WhileStmt),
    For(ForStmt),
    Case(CaseStmt),
    Function(FuncDef),
    Local(String, Option<String>),
    Break,
    Continue,
    Subshell(Script),
    Block(Script),
}

#[derive(Debug, Clone)]
pub struct SimpleCommand {
    pub env_assignments: Vec<(String, String)>,
    pub words: Vec<String>,
    pub redirections: Vec<Redirect>,
}

#[derive(Debug, Clone)]
pub enum Redirect {
    Output(String),
    Append(String),
    Input(String),
    ErrOutput(String),
    ErrAppend(String),
    ErrToOut,
    OutToErr,
}

#[derive(Debug, Clone)]
pub struct IfStmt {
