    pub words: Vec<String>,
    pub redirections: Vec<Redirect>,
}

#[derive(Debug, Clone)]
pub enum Redirect {
    Output(String),
    Append(String),
    Input(String),
    ErrOutput(String),
    ErrAppend(String),
    ErrToOut,
    OutToErr,
}

#[derive(Debug, Clone)]
pub struct IfStmt {
    pub cond: Script,
    pub then_body: Script,
    pub elifs: Vec<(Script, Script)>,
    pub else_body: Option<Script>,
}

#[derive(Debug, Clone)]
pub struct WhileStmt {
    pub cond: Script,
    pub body: Script,
}

#[derive(Debug, Clone)]
pub enum ForStmt {
    VarIn(String, Vec<String>, Script),
    Arith(String, Script),
}

#[derive(Debug, Clone)]
pub struct CaseStmt {
    pub word: String,
    pub items: Vec<(Vec<String>, Script)>,
}

#[derive(Debug, Clone)]
pub struct FuncDef {
    pub name: String,
    pub body: Script,
}

pub fn parse_script(input: &str) -> Result<Script, String> {
    let mut pairs = match ShellParser::parse(Rule::script, input) {
        Ok(p) => p,
        Err(e) => return Err(e.to_string()),
    };

    let script_pair = pairs.next().ok_or_else(|| "Empty parse".to_string())?;
    parse_script_pair(script_pair)
}

fn parse_script_pair(pair: pest::iterators::Pair<Rule>) -> Result<Script, String> {
    let mut items = Vec::new();
    for inner in pair.into_inner() {
        if inner.as_rule() == Rule::compound_list {
            for item_pair in inner.into_inner() {
                if item_pair.as_rule() == Rule::compound_list_item {
                    for and_or_pair in item_pair.into_inner() {
                        if and_or_pair.as_rule() == Rule::and_or_list {
                            items.push(parse_and_or_list(and_or_pair)?);
                        }
                    }
                }
            }
        }
    }
    Ok(Script { items })
}

fn parse_and_or_list(pair: pest::iterators::Pair<Rule>) -> Result<AndOrList, String> {
    let mut inner = pair.into_inner();
    let first_pair = inner.next().ok_or("Expected pipeline")?;
    let first = parse_pipeline(first_pair)?;

    let mut rest = Vec::new();
    while let Some(op_pair) = inner.next() {
        if op_pair.as_rule() == Rule::and_or_list_sep {
            let op = if op_pair.as_str() == "&&" { AndOrOp::And } else { AndOrOp::Or };
            let pipe_pair = inner.next().ok_or("Expected pipeline after op")?;
            let pipe = parse_pipeline(pipe_pair)?;
            rest.push((op, pipe));
        }
    }

    Ok(AndOrList { first, rest })
}

fn parse_pipeline(pair: pest::iterators::Pair<Rule>) -> Result<Pipeline, String> {
    let mut commands = Vec::new();
    let mut background = false;

    let pair_str = pair.as_str().trim();
    if pair_str.ends_with('&') && !pair_str.ends_with(">&2") && !pair_str.ends_with("2>&1") {
        background = true;
    }

    for inner in pair.into_inner() {
        if inner.as_rule() == Rule::command {
            commands.push(parse_command(inner)?);
        }
    }

    Ok(Pipeline { commands, background })
}

fn parse_command(pair: pest::iterators::Pair<Rule>) -> Result<Command, String> {
    let inner = pair.into_inner().next().ok_or("Empty command")?;
    match inner.as_rule() {
        Rule::if_stmt => parse_if_stmt(inner),
        Rule::while_stmt => parse_while_stmt(inner),
        Rule::for_stmt => parse_for_stmt(inner),
        Rule::case_stmt => parse_case_stmt(inner),
        Rule::func_def => parse_func_def(inner),
        Rule::local_stmt => parse_local_stmt(inner),
        Rule::break_stmt => Ok(Command::Break),
        Rule::continue_stmt => Ok(Command::Continue),
        Rule::subshell => parse_subshell(inner),
        Rule::block => parse_block(inner),
        Rule::simple_command => parse_simple_command(inner),
        _ => Err(format!("Unexpected rule: {:?}", inner.as_rule())),
    }
}

fn parse_if_stmt(pair: pest::iterators::Pair<Rule>) -> Result<Command, String> {
    let mut inner = pair.into_inner();
    let cond_pair = inner.next().ok_or("Expected if cond")?;
    let cond = parse_compound_list(cond_pair)?;

    let then_pair = inner.next().ok_or("Expected then body")?;
    let then_body = parse_compound_list(then_pair)?;

    let mut elifs = Vec::new();
    let mut else_body = None;

    for next_pair in inner {
        if next_pair.as_rule() == Rule::elif_clause {
            let mut elif_inner = next_pair.into_inner();
            let elif_cond = parse_compound_list(elif_inner.next().ok_or("Expected elif cond")?)?;
            let elif_body = parse_compound_list(elif_inner.next().ok_or("Expected elif body")?)?;
            elifs.push((elif_cond, elif_body));
        } else if next_pair.as_rule() == Rule::compound_list {
            else_body = Some(parse_compound_list(next_pair)?);
        }
    }

    Ok(Command::If(IfStmt { cond, then_body, elifs, else_body }))
}

fn parse_while_stmt(pair: pest::iterators::Pair<Rule>) -> Result<Command, String> {
    let mut inner = pair.into_inner();
    let cond_pair = inner.next().ok_or("Expected while cond")?;
    let cond = parse_compound_list(cond_pair)?;

    let body_pair = inner.next().ok_or("Expected while body")?;
    let body = parse_compound_list(body_pair)?;

    Ok(Command::While(WhileStmt { cond, body }))
}

fn parse_for_stmt(pair: pest::iterators::Pair<Rule>) -> Result<Command, String> {
    let mut inner = pair.into_inner();
    let first = inner.next().ok_or("Expected for init")?;

    if first.as_rule() == Rule::arith_for_exprs {
        let arith_str = first.as_str().to_string();
        let body_pair = inner.next().ok_or("Expected for body")?;
        let body = parse_compound_list(body_pair)?;
        Ok(Command::For(ForStmt::Arith(arith_str, body)))
    } else {
        let var_name = first.as_str().to_string();
        let mut words = Vec::new();
        let mut body_pair = None;

        for next_pair in inner {
            if next_pair.as_rule() == Rule::word {
                words.push(next_pair.as_str().to_string());
            } else if next_pair.as_rule() == Rule::compound_list {
                body_pair = Some(next_pair);
                break;
            }
        }

        let body = parse_compound_list(body_pair.ok_or("Expected for body")?)?;
        Ok(Command::For(ForStmt::VarIn(var_name, words, body)))
    }
}

fn parse_case_stmt(pair: pest::iterators::Pair<Rule>) -> Result<Command, String> {
    let mut inner = pair.into_inner();
    let word = inner.next().ok_or("Expected case word")?.as_str().to_string();

    let mut items = Vec::new();
    for next_pair in inner {
        if next_pair.as_rule() == Rule::case_item {
            let mut item_inner = next_pair.into_inner();
            let pat_pair = item_inner.next().ok_or("Expected pattern list")?;
            let mut pats = Vec::new();
            for pat_word in pat_pair.into_inner() {
                pats.push(pat_word.as_str().to_string());
            }
            let body = if let Some(body_pair) = item_inner.next() {
                parse_compound_list(body_pair)?
            } else {
                Script { items: Vec::new() }
            };
            items.push((pats, body));
        }
    }

    Ok(Command::Case(CaseStmt { word, items }))
}

fn parse_func_def(pair: pest::iterators::Pair<Rule>) -> Result<Command, String> {
    let mut inner = pair.into_inner();
    let name = inner.next().ok_or("Expected func name")?.as_str().to_string();
    let body_pair = inner.next().ok_or("Expected func body")?;
    let body = parse_compound_list(body_pair.into_inner().next().ok_or("Expected body list")?)?;
    Ok(Command::Function(FuncDef { name, body }))
}

fn parse_local_stmt(pair: pest::iterators::Pair<Rule>) -> Result<Command, String> {
    let mut inner = pair.into_inner();
    let assign_pair = inner.next().ok_or("Expected var assign")?;
    let mut assign_inner = assign_pair.into_inner();
    let name = assign_inner.next().ok_or("Expected var name")?.as_str().to_string();
    let val = assign_inner.next().map(|p| p.as_str().to_string());
    Ok(Command::Local(name, val))
}

fn parse_subshell(pair: pest::iterators::Pair<Rule>) -> Result<Command, String> {
    let body = parse_compound_list(pair.into_inner().next().ok_or("Expected subshell body")?)?;
    Ok(Command::Subshell(body))
}

fn parse_block(pair: pest::iterators::Pair<Rule>) -> Result<Command, String> {
    let body = parse_compound_list(pair.into_inner().next().ok_or("Expected block body")?)?;
    Ok(Command::Block(body))
}

fn parse_compound_list(pair: pest::iterators::Pair<Rule>) -> Result<Script, String> {
    let mut items = Vec::new();
    for item_pair in pair.into_inner() {
        if item_pair.as_rule() == Rule::compound_list_item {
            for and_or_pair in item_pair.into_inner() {
                if and_or_pair.as_rule() == Rule::and_or_list {
                    items.push(parse_and_or_list(and_or_pair)?);
                }
            }
        }
    }
    Ok(Script { items })
}

fn parse_simple_command(pair: pest::iterators::Pair<Rule>) -> Result<Command, String> {
    let mut env_assignments = Vec::new();
    let mut words = Vec::new();
    let mut redirections = Vec::new();

    for inner in pair.into_inner() {
        let full_str = inner.as_str().to_string();
        match inner.as_rule() {
            Rule::var_assignment => {
                let mut assign_inner = inner.into_inner();
                let name = assign_inner.next().ok_or("Expected assign name")?.as_str().to_string();
                let val = assign_inner.next().map(|p| p.as_str().to_string()).unwrap_or_default();
                env_assignments.push((name, val));
            }
            Rule::word => {
                words.push(full_str);
            }
            Rule::redirect => {
                let mut red_inner = inner.into_inner();
                if let Some(dir_pair) = red_inner.next() {
                    let dir_str = dir_pair.as_str().to_string();
                    if let Some(word_pair) = red_inner.next() {
                        let w = word_pair.as_str().to_string();
                        match dir_str.as_str() {
                            ">" => redirections.push(Redirect::Output(w)),
                            ">>" => redirections.push(Redirect::Append(w)),
                            "<" => redirections.push(Redirect::Input(w)),
                            "2>" => redirections.push(Redirect::ErrOutput(w)),
                            "2>>" => redirections.push(Redirect::ErrAppend(w)),
                            _ => {}
                        }
                    } else if dir_str == "2>&1" {
                        redirections.push(Redirect::ErrToOut);
                    } else if dir_str == "1>&2" || dir_str == ">&2" {
                        redirections.push(Redirect::OutToErr);
                    }
                } else if full_str == "2>&1" {
                    redirections.push(Redirect::ErrToOut);
                } else if full_str == "1>&2" || full_str == ">&2" {
                    redirections.push(Redirect::OutToErr);
                }
            }
            _ => {}
        }
    }

    Ok(Command::Simple(SimpleCommand {
        env_assignments,
        words,
        redirections,
    }))
}
EOF"}

