    let default_prompt_str = "\\{cyan}\\{bold}\\{current_dir} \\$ ";

    loop {
        shell.reap_jobs();

        let mut input = shell.stashed_line.take().unwrap_or_default();
        let mut cursor_pos = input.len();
        let mut history_index: Option<usize> = None;

        let prompt_pattern = shell
            .get_env("PROMPT")
            .unwrap_or_else(|| default_prompt_str.to_string());

        render_line(shell, &prompt_pattern, &input, cursor_pos);

        loop {
            if let Ok(Event::Key(key_event)) = event::read() {
                match (key_event.code, key_event.modifiers) {
                    (KeyCode::Enter, _) => {
                        println!();
                        let _ = disable_raw_mode();
                        if !input.trim().is_empty() {
                            shell.add_history(&input);
                            let _ = shell.eval_script(&input);
                        }
                        let _ = enable_raw_mode();
                        break;
                    }
                    (KeyCode::Char('c'), KeyModifiers::CONTROL) => {
                        println!("^C");
                        input.clear();
                        cursor_pos = 0;
                        break;
                    }
                    (KeyCode::Char('l'), KeyModifiers::CONTROL) => {
                        print!("\x1b[2J\x1b[1;1H");
                        let _ = io::stdout().flush();
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Char('r'), KeyModifiers::CONTROL) => {
                        if let Some(selected) = run_history_search(shell, false) {
                            input = selected;
                            cursor_pos = input.len();
                        }
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Char('h'), KeyModifiers::CONTROL) => {
                        if let Some(selected) = run_history_search(shell, true) {
                            input = selected;
                            cursor_pos = input.len();
                        }
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Char('q'), KeyModifiers::ALT) => {
                        shell.stashed_line = Some(input.clone());
                        input.clear();
                        cursor_pos = 0;
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Tab, _) => {
                        let candidates = completer.complete(&input[..cursor_pos]);
                        if candidates.len() == 1 {
                            let cand = &candidates[0];
                            if let Some(last_space) = input[..cursor_pos].rfind(' ') {
                                input.replace_range(last_space + 1..cursor_pos, cand);
                                cursor_pos = last_space + 1 + cand.len();
                            } else {
                                input = cand.clone() + &input[cursor_pos..];
                                cursor_pos = cand.len();
                            }
                        } else if candidates.len() > 1 {
                            render_completion_candidates(&candidates);
                        }
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Backspace, _) => {
                        if cursor_pos > 0 {
                            input.remove(cursor_pos - 1);
                            cursor_pos -= 1;
                        }
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Delete, _) => {
                        if cursor_pos < input.len() {
                            input.remove(cursor_pos);
                        }
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Left, _) | (KeyCode::Char('b'), KeyModifiers::CONTROL) => {
                        if cursor_pos > 0 {
                            cursor_pos -= 1;
                        }
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Right, _) | (KeyCode::Char('f'), KeyModifiers::CONTROL) => {
                        if cursor_pos < input.len() {
                            cursor_pos += 1;
                        }
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Home, _) | (KeyCode::Char('a'), KeyModifiers::CONTROL) => {
                        cursor_pos = 0;
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::End, _) | (KeyCode::Char('e'), KeyModifiers::CONTROL) => {
                        cursor_pos = input.len();
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Up, _) => {
                        if !shell.history.is_empty() {
                            let next_idx = match history_index {
                                None => shell.history.len() - 1,
                                Some(0) => 0,
                                Some(i) => i - 1,
                            };
                            history_index = Some(next_idx);
                            input = shell.history[next_idx].cmd.clone();
                            cursor_pos = input.len();
                        }
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Down, _) => {
                        if let Some(i) = history_index {
                            if i + 1 < shell.history.len() {
                                history_index = Some(i + 1);
                                input = shell.history[i + 1].cmd.clone();
                                cursor_pos = input.len();
                            } else {
                                history_index = None;
                                input.clear();
                                cursor_pos = 0;
                            }
                        }
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Char('w'), KeyModifiers::CONTROL) => {
                        if cursor_pos > 0 {
                            let before = &input[..cursor_pos];
                            if let Some(last_space) = before.trim_end().rfind(' ') {
                                input.drain(last_space + 1..cursor_pos);
                                cursor_pos = last_space + 1;
                            } else {
                                input.drain(0..cursor_pos);
                                cursor_pos = 0;
                            }
                        }
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Char('k'), KeyModifiers::CONTROL) => {
                        input.truncate(cursor_pos);
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    (KeyCode::Char(c), _) => {
                        input.insert(cursor_pos, c);
                        cursor_pos += 1;
                        render_line(shell, &prompt_pattern, &input, cursor_pos);
                    }
                    _ => {
                        log::warn!("unsupported key event: {:?}", key_event);
                    }
                }
            }
        }
    }
}

fn render_line(shell: &Shell, prompt_pattern: &str, input: &str, cursor_pos: usize) {
    let (term_cols, _) = size().unwrap_or((80, 24));
    let expanded_prompt = expand_prompt(prompt_pattern);

    let unterm_spaces = " ".repeat((term_cols as usize).saturating_sub(1));
    print!("\x1b[1m\x1b[7m$\x1b[0m{}\r", unterm_spaces);

    print!("{}", expanded_prompt);

    let highlighted = highlight_syntax(shell, input);

    let prompt_visible_len = strip_ansi(&expanded_prompt).len();
    print!("\x1b[?25l\r\x1b[{}C\x1b[K{}", prompt_visible_len, highlighted);

    let target_col = prompt_visible_len + cursor_pos;
    print!("\r\x1b[{}C\x1b[?25h", target_col);
    let _ = io::stdout().flush();
}

fn highlight_syntax(shell: &Shell, input: &str) -> String {
    if input.is_empty() {
        return String::new();
    }

    let words: Vec<&str> = input.split_whitespace().collect();
    if words.is_empty() {
        return input.to_string();
    }

    let first_word = words[0];
    let is_valid = is_builtin(first_word)
        || shell.functions.contains_key(first_word)
        || shell.aliases.contains_key(first_word)
        || is_executable_in_path(first_word);

    let cmd_color = if is_valid { "\x1b[38;5;10m" } else { "\x1b[38;5;9m" };

    let mut result = String::new();
    let mut in_cmd = true;
    let mut in_quote = None;

    for c in input.chars() {
        if c == '"' || c == '\'' {
            if in_quote == Some(c) {
                result.push(c);
                result.push_str("\x1b[0m");
                in_quote = None;
            } else if in_quote.is_none() {
                in_quote = Some(c);
                result.push_str("\x1b[38;5;14m");
                result.push(c);
            } else {
                result.push(c);
            }
        } else if in_quote.is_some() {
            result.push(c);
        } else if c == '|' || c == '&' || c == ';' {
            result.push_str(&format!("\x1b[1m\x1b[38;5;12m{}\x1b[0m", c));
            in_cmd = true;
        } else if c == '$' {
            result.push_str("\x1b[1m$");
        } else if in_cmd {
            if c.is_whitespace() {
                result.push_str("\x1b[0m");
                result.push(c);
                in_cmd = false;
            } else {
                if !result.ends_with(cmd_color) {
                    result.push_str(cmd_color);
                }
                result.push(c);
            }
        } else {
            result.push(c);
        }
    }
    result.push_str("\x1b[0m");
    result
}

fn is_executable_in_path(cmd: &str) -> bool {
    if cmd.contains('/') {
        return Path::new(cmd).is_file();
    }
    if let Ok(path_env) = std::env::var("PATH") {
        for dir in path_env.split(':') {
            if Path::new(dir).join(cmd).is_file() {
                return true;
            }
        }
    }
    false
}

fn strip_ansi(s: &str) -> String {
    let mut res = String::new();
    let mut in_esc = false;
    for c in s.chars() {
        if c == '\x1b' {
            in_esc = true;
        } else if in_esc {
            if c.is_alphabetic() {
                in_esc = false;
            }
        } else {
            res.push(c);
        }
    }
    res
}

fn render_completion_candidates(candidates: &[String]) {
    print!("\r\n");
    for (i, cand) in candidates.iter().enumerate() {
        if i == 0 {
            print!("\x1b[7m{}\x1b[27m", cand);
        } else {
            print!("  {}", cand);
        }
    }
    print!("\x1b[1A");
}

fn run_history_search(shell: &Shell, current_dir_only: bool) -> Option<String> {
    print!("\x1b[?1049h\x1b[2J\x1b[0m\x1b[1;1H");

    let prompt_prefix = if current_dir_only {
        "history (cwd)> "
    } else {
        "history> "
    };

    let cwd = std::env::current_dir()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_default();

    let mut query = String::new();
    let mut selected_idx = 0;

    loop {
        let filtered: Vec<&String> = shell
            .history
            .iter()
            .rev()
            .filter(|e| !current_dir_only || e.cwd == cwd)
            .map(|e| &e.cmd)
            .filter(|cmd| query.is_empty() || cmd.contains(&query))
            .collect();

        print!("\x1b[1;1H\x1b[1m{}\x1b[0m{}\x1b[K\r\n", prompt_prefix, query);

        for (i, item) in filtered.iter().take(20).enumerate() {
            if i == selected_idx {
                print!("\x1b[38;5;10m\x1b[1m\x1b[4m{}\x1b[0m\x1b[K\r\n", item);
            } else {
                print!("{}\x1b[K\r\n", item);
            }
        }

        print!("\x1b[24;1H\x1b[1m\x1b[7m Enter: Execute, Tab: Edit, ^C: Quit \x1b[0m");

        let cur_col = prompt_prefix.len() + query.len() + 1;
        print!("\x1b[1;{}H", cur_col);
        let _ = io::stdout().flush();

        if let Ok(Event::Key(key)) = event::read() {
            match (key.code, key.modifiers) {
                (KeyCode::Enter, _) => {
                    print!("\x1b[?1049l");
                    let _ = io::stdout().flush();
                    return filtered.get(selected_idx).map(|s| s.to_string());
                }
                (KeyCode::Tab, _) => {
                    print!("\x1b[?1049l");
                    let _ = io::stdout().flush();
                    return filtered.get(selected_idx).map(|s| s.to_string());
                }
                (KeyCode::Char('c'), KeyModifiers::CONTROL) => {
                    print!("\x1b[?1049l");
                    let _ = io::stdout().flush();
                    return None;
                }
                (KeyCode::Up, _) => {
                    if selected_idx > 0 {
                        selected_idx -= 1;
                    }
                }
                (KeyCode::Down, _) => {
                    if selected_idx + 1 < filtered.len() {
                        selected_idx += 1;
                    }
                }
                (KeyCode::Backspace, _) => {
                    query.pop();
                    selected_idx = 0;
                }
                (KeyCode::Char(c), _) => {
                    query.push(c);
                    selected_idx = 0;
                }
                _ => {}
            }
        }
    }
}
