use std::fs::File;
use std::os::unix::io::AsRawFd;
use std::path::{Path, PathBuf};

use crate::builtins::{is_builtin, run_builtin, BuiltinResult};
use crate::parser::{Redirect, SimpleCommand};
use crate::shell::Shell;

pub fn execute_simple_command(shell: &mut Shell, cmd: &SimpleCommand) -> i32 {
    if cmd.words.is_empty() {
        for (k, v) in &cmd.env_assignments {
            let expanded_v = crate::expand::expand_word(shell, v).join(" ");
            shell.set_var(k, &expanded_v);
        }
        return 0;
    }

    let mut expanded_words = Vec::new();
    for w in &cmd.words {
        let ex = crate::expand::expand_word(shell, w);
        expanded_words.extend(ex);
    }

    if expanded_words.is_empty() {
        return 0;
    }

    let first_word = &expanded_words[0];
    if let Some(alias_val) = shell.aliases.get(first_word).cloned() {
        let mut new_script = alias_val;
        if expanded_words.len() > 1 {
            new_script.push(' ');
            new_script.push_str(&expanded_words[1..].join(" "));
        }
        return match shell.eval_script(&new_script) {
            BuiltinResult::Success => 0,
            BuiltinResult::Exit(c) | BuiltinResult::Error(c) => c,
        };
    }

    if let Some(fn_body) = shell.functions.get(first_word).cloned() {
        let old_pos = shell.positional_args.clone();
        shell.positional_args = expanded_words[1..].to_vec();
        let res = shell.eval_script(&fn_body);
        shell.positional_args = old_pos;
        return match res {
            BuiltinResult::Success => 0,
            BuiltinResult::Exit(c) | BuiltinResult::Error(c) => c,
        };
    }

    if is_builtin(first_word) {
        for (k, v) in &cmd.env_assignments {
            let expanded_v = crate::expand::expand_word(shell, v).join(" ");
            shell.set_var(k, &expanded_v);
        }
        return match run_builtin(shell, &expanded_words) {
            BuiltinResult::Success => 0,
            BuiltinResult::Exit(c) | BuiltinResult::Error(c) => c,
        };
    }

    execute_external(shell, &expanded_words, &cmd.env_assignments, &cmd.redirections)
}

fn resolve_binary(cmd: &str) -> Option<PathBuf> {
    if cmd.contains('/') {
        let p = PathBuf::from(cmd);
        if p.exists() {
            return Some(p);
        }
        return None;
    }

    if let Ok(path_env) = env::var("PATH") {
        for dir in path_env.split(':') {
            let p = Path::new(dir).join(cmd);
            if p.exists() {
                return Some(p);
            }
        }
    }
    None
}

fn execute_external(
    shell: &mut Shell,
    args: &[String],
    env_assigns: &[(String, String)],
    redirections: &[Redirect],
) -> i32 {
    let cmd_name = &args[0];
    let resolved = match resolve_binary(cmd_name) {
        Some(p) => p,
        None => {
            eprintln!("nsh: command not found `{}`", cmd_name);
            return 1;
        }
    };

    use std::os::unix::fs::PermissionsExt;
    if let Ok(metadata) = std::fs::metadata(&resolved) {
        if metadata.is_dir() || (metadata.permissions().mode() & 0o111) == 0 {
            eprintln!(
                "nsh: Failed to exec \"{}\" (EACCESS). chmod(1) may help.",
                resolved.to_string_lossy()
            );
            return 1;
        }
    }

    unsafe {
        let pid = libc::fork();
        if pid < 0 {
            eprintln!("nsh: fork failed");
            return 1;
        }

        if pid == 0 {
            for red in redirections {
                match red {
                    Redirect::Output(target) => {
                        let expanded = crate::expand::expand_word(shell, target).join(" ");
                        if let Ok(file) = File::create(&expanded) {
                            libc::dup2(file.as_raw_fd(), libc::STDOUT_FILENO);
                        }
                    }
                    Redirect::Append(target) => {
                        let expanded = crate::expand::expand_word(shell, target).join(" ");
                        if let Ok(file) = std::fs::OpenOptions::new().append(true).create(true).open(&expanded) {
                            libc::dup2(file.as_raw_fd(), libc::STDOUT_FILENO);
                        }
                    }
                    Redirect::Input(target) => {
                        let expanded = crate::expand::expand_word(shell, target).join(" ");
                        if let Ok(file) = File::open(&expanded) {
                            libc::dup2(file.as_raw_fd(), libc::STDIN_FILENO);
                        }
                    }
                    Redirect::ErrOutput(target) => {
                        let expanded = crate::expand::expand_word(shell, target).join(" ");
                        if let Ok(file) = File::create(&expanded) {
                            libc::dup2(file.as_raw_fd(), libc::STDERR_FILENO);
                        }
                    }
                    Redirect::ErrAppend(target) => {
                        let expanded = crate::expand::expand_word(shell, target).join(" ");
                        if let Ok(file) = std::fs::OpenOptions::new().append(true).create(true).open(&expanded) {
                            libc::dup2(file.as_raw_fd(), libc::STDERR_FILENO);
                        }
                    }
                    Redirect::ErrToOut => {
                        libc::dup2(libc::STDOUT_FILENO, libc::STDERR_FILENO);
                    }
                    Redirect::OutToErr => {
                        libc::dup2(libc::STDERR_FILENO, libc::STDOUT_FILENO);
                    }
                }
            }

            for (k, v) in env_assigns {
                let expanded_v = crate::expand::expand_word(shell, v).join(" ");
                env::set_var(k, expanded_v);
            }

            let c_cmd = CString::new(resolved.to_string_lossy().as_bytes()).unwrap();
            let c_args: Vec<CString> = args
                .iter()
                .map(|a| CString::new(a.as_bytes()).unwrap())
                .collect();
            let mut arg_ptrs: Vec<*const libc::c_char> = c_args.iter().map(|s| s.as_ptr()).collect();
            arg_ptrs.push(std::ptr::null());

            let env_vars: Vec<CString> = env::vars()
                .map(|(k, v)| CString::new(format!("{}={}", k, v).as_bytes()).unwrap())
                .collect();
            let mut env_ptrs: Vec<*const libc::c_char> = env_vars.iter().map(|s| s.as_ptr()).collect();
            env_ptrs.push(std::ptr::null());

            libc::execve(c_cmd.as_ptr(), arg_ptrs.as_ptr(), env_ptrs.as_ptr());
            libc::_exit(127);
        } else {
            let mut status = 0;
            libc::waitpid(pid, &mut status, 0);
            if libc::WIFEXITED(status) {
                return libc::WEXITSTATUS(status);
            } else if libc::WIFSIGNALED(status) {
                return 128 + libc::WTERMSIG(status);
            }
            return 1;
        }
    }
}
