    match stmt {
        ForStmt::VarIn(var_name, words, body) => {
            let mut expanded_words = Vec::new();
            for w in words {
                expanded_words.extend(crate::expand::expand_word(shell, w));
            }
            let mut last_res = BuiltinResult::Success;
            for val in expanded_words {
                shell.set_var(var_name, &val);
                last_res = eval_parsed_script(shell, body);
                if let BuiltinResult::Exit(_) = last_res {
                    return last_res;
                }
            }
            last_res
        }
        ForStmt::Arith(_arith_str, body) => {
            let mut last_res = BuiltinResult::Success;
            let mut count = 0;
            while count < 1000 {
                last_res = eval_parsed_script(shell, body);
                if let BuiltinResult::Exit(_) = last_res {
                    return last_res;
                }
                count += 1;
            }
            last_res
        }
    }
}

fn eval_case(shell: &mut Shell, stmt: &CaseStmt) -> BuiltinResult {
    let target = crate::expand::expand_word(shell, &stmt.word).join(" ");
    for (pats, body) in &stmt.items {
        for pat in pats {
            let expanded_pat = crate::expand::expand_word(shell, pat).join(" ");
            if glob_match(&expanded_pat, &target) {
                return eval_parsed_script(shell, body);
            }
        }
    }
    BuiltinResult::Success
}
