                        if let Ok(file) = std::fs::OpenOptions::new().append(true).create(true).open(&expanded) {
                            libc::dup2(file.as_raw_fd(), libc::STDERR_FILENO);
                        }
                    }
                    Redirect::ErrToOut => {
                        libc::dup2(libc::STDOUT_FILENO, libc::STDERR_FILENO);
                    }
                    Redirect::OutToErr => {
                        libc::dup2(libc::STDERR_FILENO, libc::STDOUT_FILENO);
                    }
                }
            }

            for (k, v) in env_assigns {
                let expanded_v = crate::expand::expand_word(shell, v).join(" ");
                env::set_var(k, expanded_v);
            }

            let c_cmd = CString::new(resolved.to_string_lossy().as_bytes()).unwrap();
            let c_args: Vec<CString> = args
                .iter()
                .map(|a| CString::new(a.as_bytes()).unwrap())
                .collect();
            let mut arg_ptrs: Vec<*const libc::c_char> = c_args.iter().map(|s| s.as_ptr()).collect();
            arg_ptrs.push(std::ptr::null());

            let env_vars: Vec<CString> = env::vars()
                .map(|(k, v)| CString::new(format!("{}={}", k, v).as_bytes()).unwrap())
                .collect();
            let mut env_ptrs: Vec<*const libc::c_char> = env_vars.iter().map(|s| s.as_ptr()).collect();
            env_ptrs.push(std::ptr::null());

            libc::execve(c_cmd.as_ptr(), arg_ptrs.as_ptr(), env_ptrs.as_ptr());
            libc::_exit(127);
        } else {
            let mut status = 0;
            libc::waitpid(pid, &mut status, 0);
            if libc::WIFEXITED(status) {
                return libc::WEXITSTATUS(status);
            } else if libc::WIFSIGNALED(status) {
                return 128 + libc::WTERMSIG(status);
            }
            return 1;
        }
    }
}
