fn parse_for_stmt(pair: pest::iterators::Pair<Rule>) -> Result<Command, String> {
    let mut inner = pair.into_inner();
    let first = inner.next().ok_or("Expected for init")?;

    if first.as_rule() == Rule::arith_for_exprs {
        let arith_str = first.as_str().to_string();
        let body_pair = inner.next().ok_or("Expected for body")?;
        let body = parse_compound_list_pair(body_pair)?;
